import { unstable_cache } from 'next/cache';
import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cache the DB call and tag it so revalidateTag('products') can invalidate it.
// No time-based expiry — the catalog stays fresh until an explicit sync is triggered.
const getCachedProducts = unstable_cache(
  () => getAllProducts(),
  ['products'],
  { tags: ['products'] },
);

const STATUS_LABELS: Record<string, { label: string; color: string }> = {
  active:        { label: 'Active',        color: '#16a34a' },
  low_stock:     { label: 'Low stock',     color: '#d97706' },
  out_of_stock:  { label: 'Out of stock',  color: '#dc2626' },
  discontinued:  { label: 'Discontinued',  color: '#6b7280' },
};

export default async function CatalogPage() {
  const products = await getCachedProducts();

  // Inline Server Action — runs on the server when the form is submitted.
  // Marks the 'products' cache tag as stale so the next render re-fetches
  // from the DB, picking up whatever the upstream ERP/PIM sync has written.
  // The action returns quickly; the admin does not wait for the sync job itself.
  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 960, margin: '0 auto', padding: '2rem 1.5rem' }}>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', gap: '1rem', flexWrap: 'wrap' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
          <p style={{ margin: '0.25rem 0 0', color: '#6b7280', fontSize: '0.875rem' }}>
            {products.length} SKUs &mdash; cached, served instantly on every request
          </p>
        </div>

        {/* Regular HTML form — submission triggers the inline Server Action above.
            revalidateTag('products') marks the cache stale; the next catalog
            request will re-fetch from the DB once the background sync has landed
            new data. The admin gets a response immediately and can keep working. */}
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1.25rem',
              background: '#2563eb',
              color: '#fff',
              border: 'none',
              borderRadius: '0.375rem',
              fontSize: '0.875rem',
              fontWeight: 500,
              cursor: 'pointer',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
          <thead>
            <tr style={{ background: '#f9fafb', borderBottom: '2px solid #e5e7eb' }}>
              {['SKU', 'Name', 'Price', 'Stock', 'Status'].map((col) => (
                <th
                  key={col}
                  style={{
                    padding: '0.75rem 1rem',
                    textAlign: col === 'Price' || col === 'Stock' ? 'right' : 'left',
                    fontWeight: 600,
                    color: '#374151',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {products.map((product) => {
              const badge = STATUS_LABELS[product.status] ?? { label: product.status, color: '#6b7280' };
              return (
                <tr key={product.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
                  <td style={{ padding: '0.75rem 1rem', color: '#6b7280', fontFamily: 'monospace' }}>
                    {product.sku}
                  </td>
                  <td style={{ padding: '0.75rem 1rem', fontWeight: 500 }}>
                    {product.name}
                  </td>
                  <td style={{ padding: '0.75rem 1rem', textAlign: 'right' }}>
                    ${product.price.toLocaleString()}
                  </td>
                  <td style={{ padding: '0.75rem 1rem', textAlign: 'right' }}>
                    {product.stock}
                  </td>
                  <td style={{ padding: '0.75rem 1rem' }}>
                    <span style={{
                      display: 'inline-block',
                      padding: '0.125rem 0.5rem',
                      borderRadius: '9999px',
                      fontSize: '0.75rem',
                      fontWeight: 500,
                      color: badge.color,
                      background: badge.color + '1a',
                    }}>
                      {badge.label}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </main>
  );
}

